#!/usr/bin/env node
// Fake Claude Code for the Ensemble E2E tests. The command line matches the `@anthropic-ai/claude-code` agent rule.
// - Logs its argv (and what happens) as JSON lines to $FAKE_ENSEMBLE_LOG.
// - Writes session registry states like Claude Code ($CLAUDE_CONFIG_DIR/sessions/<pid>.json).
// - Turns bracketed paste on and reads pasted messages (raw input, like a TUI); on "[Ensemble] … assignment" it
//   reads the context in the message (oxy_ensemble_context only when it was cut) and calls oxy_ensemble_submit over
//   HTTP with the server and token of its --mcp-config file; questions are answered with oxy_ensemble_answer.
// - $FAKE_ENSEMBLE_SCRIPT (JSON) scripts each agent by name, one step per assignment:
//   { "Grace": [{ "verdict": "changes" }, { "verdict": "approve" }], "Linus": [{ "ask": { "to": "Ada", "question": "?" } }] }
//   A step may also have "asks": [{ "to", "question" }], "writeFile": "path", "skipSubmit": true, "waitMs": 2000 and
//   "usage": { "model": "claude-opus-5-5", "output": 1000 } (a usage line in the session log, like Claude Code) and
//   "delegate": [{ "to": "Tim", "work": "…" }] (delegates, then submits once every report arrived).
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');

const args = process.argv.slice(2);
const opt = (name) => {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : undefined;
};
const name = (opt('--name') || 'ens:x/agent').split('/').pop();
const logFile = process.env.FAKE_ENSEMBLE_LOG;
const log = (entry) => {
  if (logFile) fs.appendFileSync(logFile, `${JSON.stringify({ agent: name, pid: process.pid, ...entry })}\n`);
};
log({ event: 'start', args, cwd: process.cwd() });

const configDir = process.env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude');
const sessionsDir = path.join(configDir, 'sessions');
const registry = path.join(sessionsDir, `${process.pid}.json`);
const sessionId = opt('--resume') || opt('--session-id') || `fake-${process.pid}`;
function status(value) {
  fs.mkdirSync(sessionsDir, { recursive: true });
  const entry = { pid: process.pid, sessionId, cwd: process.cwd(), name, status: value, updatedAt: Date.now() };
  fs.writeFileSync(`${registry}.tmp`, JSON.stringify(entry));
  fs.renameSync(`${registry}.tmp`, registry);
}
function cleanup() {
  try {
    fs.unlinkSync(registry);
  } catch {
    // already gone
  }
}

const config = JSON.parse(fs.readFileSync(opt('--mcp-config'), 'utf8'));
const server = Object.values(config.mcpServers)[0];
let mcpSession = null;
let rpcId = 0;
async function rpc(method, params) {
  const res = await fetch(server.url, {
    method: 'POST',
    headers: {
      ...server.headers,
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
      ...(mcpSession ? { 'Mcp-Session-Id': mcpSession } : {}),
    },
    body: JSON.stringify({ jsonrpc: '2.0', id: ++rpcId, method, params }),
  });
  if (!mcpSession) mcpSession = res.headers.get('mcp-session-id');
  const json = await res.json();
  if (json.error) throw new Error(json.error.message);
  return json.result;
}
async function tool(toolName, toolArgs) {
  if (!mcpSession) await rpc('initialize', { protocolVersion: '2025-06-18' });
  const result = await rpc('tools/call', { name: toolName, arguments: toolArgs });
  const text = (result.content || []).map((c) => c.text).join('\n');
  log({ event: 'tool', tool: toolName, isError: !!result.isError, text: text.slice(0, 4000) });
  return { text, isError: !!result.isError };
}

let usageLines = 0;
function writeUsage(usage) {
  const dir = path.join(configDir, 'projects', process.cwd().replace(/[^a-zA-Z0-9]/g, '-'));
  fs.mkdirSync(dir, { recursive: true });
  const id = `msg_${process.pid}_${++usageLines}`;
  const line = {
    type: 'assistant',
    timestamp: new Date().toISOString(),
    sessionId,
    uuid: `u-${id}`,
    isSidechain: false,
    version: '2.1.283',
    cwd: process.cwd(),
    requestId: `req_${id}`,
    message: {
      type: 'message',
      role: 'assistant',
      model: usage.model || 'claude-opus-5-5',
      id,
      content: [{ type: 'text' }],
      usage: { input_tokens: usage.input || 0, output_tokens: usage.output || 0 },
    },
  };
  fs.appendFileSync(path.join(dir, `${sessionId}.jsonl`), `${JSON.stringify(line)}\n`);
  log({ event: 'usage', text: id });
}

const script = process.env.FAKE_ENSEMBLE_SCRIPT ? JSON.parse(fs.readFileSync(process.env.FAKE_ENSEMBLE_SCRIPT, 'utf8')) : {};
const steps = script[name] || [];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
/** Delegated work this agent waits for before it submits. */
let pending = null;

async function onMessage(text) {
  log({ event: 'message', text });
  status('busy');
  await sleep(300);
  try {
    const question = /Question from .*\(id (q-\d+)\)/.exec(text.split('\n')[0]);
    if (question) {
      await tool('oxy_ensemble_answer', { questionId: question[1], answer: `${name} answers: use commas` });
      return;
    }
    const head = text.split('\n')[0];
    if (/Report from /.test(head) && pending) {
      pending.reports.push(text);
      if (pending.reports.length < pending.expected) return;
      const p = pending;
      pending = null;
      await tool('oxy_ensemble_submit', {
        kind: p.kind,
        summary: `${name}: ${p.kind} done with ${p.reports.length} report(s)`,
        body: `${name} got:\n${p.reports.join('\n---\n')}`,
      });
      return;
    }
    if (!/assignment|Changes requested|consulted|delegated work/.test(head)) return;
    // The assignment message carries the whole context; the tool is only needed when it was cut.
    const ctx = text.includes('## Your assignment') && !text.includes('[… cut here') ? { text } : await tool('oxy_ensemble_context', {});
    const kind = /kind \*\*"([a-z-]+)"\*\*/.exec(ctx.text);
    if (!kind) return;
    const step = steps.shift() || {};
    if (step.usage) writeUsage(step.usage);
    if (step.waitMs) await sleep(step.waitMs);
    for (const ask of step.asks || (step.ask ? [step.ask] : [])) {
      const answer = await tool('oxy_ensemble_ask', { to: ask.to, question: ask.question, wait_seconds: 60 });
      log({ event: 'answer', text: answer.text });
    }
    if (step.delegate) {
      for (const d of step.delegate) await tool('oxy_ensemble_delegate', d);
      // The submit waits for the reports (delivered as messages).
      pending = { kind: kind[1], expected: step.delegate.length, reports: [] };
      return;
    }
    if (step.writeFile) fs.writeFileSync(path.join(process.cwd(), step.writeFile), `written by ${name}\n`);
    if (step.skipSubmit) return;
    const submission = { kind: kind[1], summary: `${name}: ${kind[1]} done`, body: `${name} saw:\n${ctx.text.slice(0, 6000)}` };
    if (kind[1] === 'review') {
      submission.verdict = step.verdict || 'approve';
      submission.findings =
        submission.verdict === 'changes' ? [{ file: 'src/a.ts', line: 1, severity: 'major', message: `${name} wants a fix` }] : [];
    }
    if (kind[1] === 'advice') submission.target = step.target || 'user';
    await tool('oxy_ensemble_submit', submission);
  } catch (e) {
    log({ event: 'error', text: String(e && e.message) });
  } finally {
    status('idle');
    process.stdout.write('ens> ');
  }
}

// Like the real CLIs: the MCP servers connect at start-up.
rpc('initialize', { protocolVersion: '2025-06-18' })
  .then(() => rpc('tools/list', {}))
  .then(() => log({ event: 'mcp-connected' }))
  .catch((e) => log({ event: 'error', text: String(e && e.message) }));
status('idle');
process.stdout.write(`\x1b[?2004hFake Claude Code (Ensemble) ${name} ready\r\nens> `);
let queue = Promise.resolve();
// Raw input like a real TUI: a bracketed paste is one message (newlines included), Enter submits it.
if (process.stdin.isTTY) process.stdin.setRawMode(true);
process.stdin.setEncoding('utf8');
let input = '';
let pasting = false;
function submit() {
  const text = input.trim();
  input = '';
  if (!text) return;
  if (text === 'quit') {
    cleanup();
    process.exit(0);
  }
  log({ event: 'received', text: text.slice(0, 200), length: text.length });
  queue = queue.then(() => onMessage(text));
}
process.stdin.on('data', (chunk) => {
  let rest = chunk;
  while (rest.length) {
    if (pasting) {
      const end = rest.indexOf('\x1b[201~');
      if (end < 0) {
        input += rest;
        return;
      }
      input += rest.slice(0, end);
      rest = rest.slice(end + 6);
      pasting = false;
      continue;
    }
    const start = rest.indexOf('\x1b[200~');
    const enter = rest.search(/[\r\n]/);
    if (start >= 0 && (enter < 0 || start < enter)) {
      input += rest.slice(0, start);
      rest = rest.slice(start + 6);
      pasting = true;
      continue;
    }
    if (enter >= 0) {
      input += rest.slice(0, enter);
      rest = rest.slice(enter + 1);
      submit();
      continue;
    }
    if (rest.includes('\x03')) {
      cleanup();
      process.exit(0);
    }
    input += rest;
    return;
  }
});
for (const signal of ['SIGINT', 'SIGTERM', 'SIGHUP']) {
  process.on(signal, () => {
    cleanup();
    process.exit(0);
  });
}
process.stdin.on('end', () => {
  cleanup();
  process.exit(0);
});
